CREATE TABLE recent_results(id TEXT NOT NULL,dataset_version TEXT NOT NULL,league_id TEXT NOT NULL REFERENCES leagues(id),season TEXT NOT NULL,match_date TEXT NOT NULL,home_id TEXT NOT NULL REFERENCES teams(id),away_id TEXT NOT NULL REFERENCES teams(id),home_goals INTEGER NOT NULL CHECK(home_goals>=0),away_goals INTEGER NOT NULL CHECK(away_goals>=0),quality TEXT NOT NULL,provenance TEXT NOT NULL,PRIMARY KEY(id,dataset_version),CHECK(home_id<>away_id),UNIQUE(league_id,season,home_id,away_id,dataset_version));
CREATE TRIGGER recent_results_no_update BEFORE UPDATE ON recent_results BEGIN SELECT RAISE(ABORT,'historical_dataset_immutable'); END;
CREATE TRIGGER recent_results_no_delete BEFORE DELETE ON recent_results BEGIN SELECT RAISE(ABORT,'historical_dataset_immutable'); END;
CREATE INDEX recent_results_home ON recent_results(home_id,league_id,match_date);
CREATE INDEX recent_results_away ON recent_results(away_id,league_id,match_date);
CREATE INDEX recent_results_h2h ON recent_results(home_id,away_id,match_date);
CREATE TABLE analysis_snapshots(id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL REFERENCES fixtures(id),generated_at TEXT NOT NULL,cutoff_date TEXT NOT NULL,model_version TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode='mock_research'),UNIQUE(fixture_id,generated_at,model_version));
CREATE TRIGGER analysis_snapshot_no_update BEFORE UPDATE ON analysis_snapshots BEGIN SELECT RAISE(ABORT,'analysis_snapshot_immutable'); END;
CREATE TRIGGER analysis_snapshot_no_delete BEFORE DELETE ON analysis_snapshots BEGIN SELECT RAISE(ABORT,'analysis_snapshot_immutable'); END;
CREATE TABLE daily_report_snapshots(id TEXT PRIMARY KEY,round_date TEXT NOT NULL,period TEXT NOT NULL CHECK(period IN('day','night')),generated_at TEXT NOT NULL,policy_version TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode='mock_research'));
CREATE INDEX daily_report_round ON daily_report_snapshots(round_date,period,generated_at);
CREATE TRIGGER daily_report_no_update BEFORE UPDATE ON daily_report_snapshots BEGIN SELECT RAISE(ABORT,'daily_report_immutable'); END;
CREATE TRIGGER daily_report_no_delete BEFORE DELETE ON daily_report_snapshots BEGIN SELECT RAISE(ABORT,'daily_report_immutable'); END;
CREATE TABLE research_report_chunks(report_key TEXT NOT NULL,part INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(report_key,part));
CREATE TRIGGER report_chunk_no_update BEFORE UPDATE ON research_report_chunks BEGIN SELECT RAISE(ABORT,'report_chunk_immutable'); END;
CREATE TRIGGER report_chunk_no_delete BEFORE DELETE ON research_report_chunks BEGIN SELECT RAISE(ABORT,'report_chunk_immutable'); END;
CREATE TABLE daily_report_evaluations(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES daily_report_snapshots(id),evaluated_at TEXT NOT NULL,payload TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE INDEX report_evaluations_time ON daily_report_evaluations(report_id,evaluated_at);
CREATE TRIGGER report_eval_no_update BEFORE UPDATE ON daily_report_evaluations BEGIN SELECT RAISE(ABORT,'report_evaluation_immutable'); END;
CREATE TRIGGER report_eval_no_delete BEFORE DELETE ON daily_report_evaluations BEGIN SELECT RAISE(ABORT,'report_evaluation_immutable'); END;
